<script>
  const sidebar=document.getElementById('sidebar'),appMenu=document.getElementById('appMenu'),themeMenu=document.getElementById('themeMenu'),palette=document.getElementById('commandPalette'),mobileOverlay=document.getElementById('mobileOverlay');
  const applyWorkspaceTheme=(preference)=>{const theme=preference==='system'?(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):preference;sidebar.dataset.theme=theme;document.body.dataset.theme=theme;localStorage.setItem('skillspot-theme',preference)};
  applyWorkspaceTheme(localStorage.getItem('skillspot-theme')||localStorage.getItem('skillspot-sidebar-theme')||'dark');
  document.getElementById('sidebarToggle').addEventListener('click',()=>{sidebar.classList.toggle('is-collapsed');localStorage.setItem('skillspot-sidebar-collapsed',sidebar.classList.contains('is-collapsed'))});if(localStorage.getItem('skillspot-sidebar-collapsed')==='true')sidebar.classList.add('is-collapsed');
  document.getElementById('appMenuButton').addEventListener('click',()=>{appMenu.classList.toggle('is-open');document.getElementById('appMenuButton').setAttribute('aria-expanded',appMenu.classList.contains('is-open'));themeMenu.classList.remove('is-open')});document.getElementById('themeMenuButton').addEventListener('click',()=>themeMenu.classList.toggle('is-open'));document.querySelectorAll('[data-sidebar-theme]').forEach(button=>button.addEventListener('click',()=>{applyWorkspaceTheme(button.dataset.sidebarTheme);themeMenu.classList.remove('is-open');appMenu.classList.remove('is-open')}));
  document.getElementById('notificationsButton').addEventListener('click',()=>document.getElementById('notificationPanel').classList.toggle('is-open'));const openPalette=()=>{palette.classList.add('is-open');document.getElementById('commandInput').focus()},closePalette=()=>palette.classList.remove('is-open');document.getElementById('searchButton').addEventListener('click',openPalette);document.getElementById('commandClose').addEventListener('click',closePalette);palette.addEventListener('click',event=>{if(event.target===palette)closePalette()});document.getElementById('commandInput').addEventListener('input',event=>document.querySelectorAll('[data-command-item]').forEach(item=>item.classList.toggle('hidden',!item.dataset.commandItem.includes(event.target.value.toLowerCase()))));
  const settingsModal=document.getElementById('settingsModal'),settingsFrame=document.getElementById('settingsFrame'),settingsTab=()=>location.hash.match(/^#settings\/([a-z-]+)$/)?.[1],showSettings=(tab,addHistory=false)=>{const activeTab=tab||'general';settingsModal.classList.remove('hidden');appMenu.classList.remove('is-open');if(settingsFrame.dataset.tab!==activeTab){settingsFrame.src=`{{ route('admin.settings') }}?tab=${encodeURIComponent(activeTab)}&embed=1`;settingsFrame.dataset.tab=activeTab}if(addHistory)history.pushState({settingsTab:activeTab},'',`${location.pathname}${location.search}#settings/${activeTab}`)},openSettings=()=>showSettings(settingsTab()||'general',!settingsTab()),closeSettings=()=>{settingsModal.classList.add('hidden');if(settingsTab())history.pushState({},'',`${location.pathname}${location.search}`)};document.getElementById('settingsModalButton')?.addEventListener('click',openSettings);settingsModal.addEventListener('click',event=>{if(event.target===settingsModal)closeSettings()});window.addEventListener('message',event=>{if(event.origin!==window.location.origin)return;if(event.data==='skillspot:close-settings')return closeSettings();if(event.data?.type==='skillspot:navigate-settings'&&/^[a-z-]+$/.test(event.data.tab))showSettings(event.data.tab,true)});window.addEventListener('popstate',()=>{const tab=settingsTab();tab?showSettings(tab):settingsModal.classList.add('hidden')});if(settingsTab())showSettings(settingsTab());
  window.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openPalette()}if(event.key==='Escape'){closePalette();closeSettings();appMenu.classList.remove('is-open');themeMenu.classList.remove('is-open')}});const openMobileSidebar=()=>{sidebar.style.transform='translateX(0)';mobileOverlay.classList.remove('hidden')},closeMobileSidebar=()=>{sidebar.style.transform='translateX(-100%)';mobileOverlay.classList.add('hidden')};document.getElementById('mobileMenuBtn').addEventListener('click',openMobileSidebar);mobileOverlay.addEventListener('click',closeMobileSidebar);if(window.innerWidth<1024){sidebar.style.transform='translateX(-100%)';sidebar.style.transition='transform .2s ease'}
</script>
